//! Windows user-bound DPAPI protection for resumable HTTP cookie state.
use crate::Result;
#[cfg(windows)]mod windows{
 use super::*;
 #[repr(C)]struct Blob{size:u32,data:*mut u8}
 #[link(name="Crypt32")]extern "system"{fn CryptProtectData(input:*const Blob,description:*const u16,entropy:*const Blob,reserved:*mut core::ffi::c_void,prompt:*mut core::ffi::c_void,flags:u32,output:*mut Blob)->i32;fn CryptUnprotectData(input:*const Blob,description:*mut *mut u16,entropy:*const Blob,reserved:*mut core::ffi::c_void,prompt:*mut core::ffi::c_void,flags:u32,output:*mut Blob)->i32;}
 #[link(name="Kernel32")]extern "system"{fn LocalFree(memory:*mut core::ffi::c_void)->*mut core::ffi::c_void;}
 pub fn convert(bytes:&[u8],decrypt:bool)->Result<Vec<u8>>{if bytes.len()>16*1024*1024{return Err("Protected cookie state exceeds 16 MiB".into())}let entropy=b"FITIG SEO Spider HTTP cookies v1";let input=Blob{size:bytes.len()as u32,data:bytes.as_ptr()as *mut u8};let entropy=Blob{size:entropy.len()as u32,data:entropy.as_ptr()as *mut u8};let mut output=Blob{size:0,data:std::ptr::null_mut()};let ok=unsafe{if decrypt{CryptUnprotectData(&input,std::ptr::null_mut(),&entropy,std::ptr::null_mut(),std::ptr::null_mut(),1,&mut output)}else{CryptProtectData(&input,std::ptr::null(),&entropy,std::ptr::null_mut(),std::ptr::null_mut(),1,&mut output)}};if ok==0{return Err(if decrypt{"Cannot unlock cookie state with this Windows user; the saved crawl was not changed"}else{"Windows could not protect HTTP cookie state"}.into())}let value=if output.size==0{Vec::new()}else if output.data.is_null(){return Err("Windows returned an invalid protected-state buffer".into())}else{unsafe{std::slice::from_raw_parts(output.data,output.size as usize).to_vec()}};if !output.data.is_null(){unsafe{LocalFree(output.data.cast());}}Ok(value)}
}
pub fn protect(bytes:&[u8])->Result<Vec<u8>>{#[cfg(windows)]{windows::convert(bytes,false)}#[cfg(not(windows))]{let _=bytes;Err("Resumable HTTP cookies currently require Windows DPAPI".into())}}
pub fn unprotect(bytes:&[u8])->Result<Vec<u8>>{#[cfg(windows)]{windows::convert(bytes,true)}#[cfg(not(windows))]{let _=bytes;Err("Resumable HTTP cookies currently require Windows DPAPI".into())}}
#[cfg(all(test,windows))]mod tests{use super::*;#[test]fn protection_round_trips_and_rejects_tampering(){let raw=b"owned cookie value must not be plaintext";let encrypted=protect(raw).unwrap();assert!(!encrypted.windows(raw.len()).any(|bytes|bytes==raw));assert_eq!(unprotect(&encrypted).unwrap(),raw);let mut corrupted=encrypted;let i=corrupted.len()/2;corrupted[i]^=0x80;assert!(unprotect(&corrupted).is_err());}}
